package com.sathavahana.kalamkari.repository; import com.sathavahana.kalamkari.domain.Product; import org.springframework.data.jpa.repository.EntityGraph; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ProductRepository extends JpaRepository<Product,Long>{@EntityGraph(attributePaths = "category") Optional<Product> findBySlugAndActiveTrue(String slug); @EntityGraph(attributePaths = "category") List<Product> findAllByActiveTrue();}
